CREATE TYPE public.app_role AS ENUM ('admin','supervisor');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, nombre text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'supervisor', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_audit_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,nombre) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'nombre',NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'supervisor'); RETURN NEW; END $$;
CREATE TRIGGER audit_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_audit_profile();
CREATE TABLE public.instalaciones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre text NOT NULL, tipo text NOT NULL, ubicacion text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.instalaciones TO authenticated; GRANT ALL ON public.instalaciones TO service_role; ALTER TABLE public.instalaciones ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rcas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instalacion_id uuid NOT NULL REFERENCES public.instalaciones(id), numero text NOT NULL DEFAULT '', nombre text NOT NULL, fecha date NOT NULL DEFAULT CURRENT_DATE, estado text NOT NULL DEFAULT 'Vigente', archivo_path text NOT NULL, items jsonb NOT NULL DEFAULT '[]', validados boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rcas TO authenticated; GRANT ALL ON public.rcas TO service_role; ALTER TABLE public.rcas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.auditorias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instalacion_id uuid NOT NULL REFERENCES public.instalaciones(id), supervisor_id uuid NOT NULL REFERENCES public.profiles(id), rca_ids uuid[] NOT NULL, estado text NOT NULL DEFAULT 'Asignada', fecha_limite date NOT NULL, items jsonb NOT NULL, respuestas jsonb NOT NULL DEFAULT '[]', observaciones jsonb NOT NULL DEFAULT '{}', general text NOT NULL DEFAULT '', comentario_admin text NOT NULL DEFAULT '', submitted_at timestamptz, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.auditorias TO authenticated; GRANT ALL ON public.auditorias TO service_role; ALTER TABLE public.auditorias ENABLE ROW LEVEL SECURITY;
CREATE POLICY audits_read ON public.auditorias FOR SELECT TO authenticated USING(supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY audits_create ON public.auditorias FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY audits_update ON public.auditorias FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR (supervisor_id=auth.uid() AND estado IN ('Asignada','En progreso','Rechazada'))) WITH CHECK(public.has_role(auth.uid(),'admin') OR (supervisor_id=auth.uid() AND estado IN ('Asignada','En progreso','En revisión','Rechazada')));
CREATE POLICY installation_read ON public.instalaciones FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.auditorias a WHERE a.instalacion_id=id AND a.supervisor_id=auth.uid()));
CREATE POLICY installation_manage ON public.instalaciones FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY rca_read ON public.rcas FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.auditorias a WHERE rcas.id=ANY(a.rca_ids) AND a.supervisor_id=auth.uid()));
CREATE POLICY rca_manage ON public.rcas FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.evidencias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auditoria_id uuid NOT NULL REFERENCES public.auditorias(id), item_id text NOT NULL, archivo_path text NOT NULL UNIQUE, nombre text NOT NULL, mime text NOT NULL, uploaded_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.evidencias TO authenticated; GRANT ALL ON public.evidencias TO service_role; ALTER TABLE public.evidencias ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_read ON public.evidencias FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.auditorias a WHERE a.id=auditoria_id));
CREATE POLICY evidence_insert ON public.evidencias FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND EXISTS(SELECT 1 FROM public.auditorias a WHERE a.id=auditoria_id AND a.estado IN ('Asignada','En progreso','Rechazada') AND (a.supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY evidence_delete ON public.evidencias FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.auditorias a WHERE a.id=auditoria_id AND a.estado IN ('Asignada','En progreso','Rechazada') AND (a.supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE FUNCTION public.validate_audit_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND current_user NOT IN ('postgres','service_role') THEN IF NEW.instalacion_id IS DISTINCT FROM OLD.instalacion_id OR NEW.supervisor_id IS DISTINCT FROM OLD.supervisor_id OR NEW.rca_ids IS DISTINCT FROM OLD.rca_ids OR NEW.items IS DISTINCT FROM OLD.items OR NEW.fecha_limite IS DISTINCT FROM OLD.fecha_limite OR NEW.comentario_admin IS DISTINCT FROM OLD.comentario_admin OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at THEN RAISE EXCEPTION 'No puedes modificar la asignación ni la revisión'; END IF; END IF; IF NEW.estado='En revisión' THEN IF jsonb_array_length(NEW.respuestas)<>jsonb_array_length(NEW.items) OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.respuestas) r WHERE r='null'::jsonb OR r#>>'{}' NOT IN ('cumple','no_cumple','no_aplica')) THEN RAISE EXCEPTION 'Completa todos los ítems'; END IF; NEW.submitted_at=now(); END IF; IF NEW.estado='Aprobada' AND OLD.estado<>'En revisión' THEN RAISE EXCEPTION 'Solo puedes aprobar una auditoría en revisión'; END IF; IF NEW.estado='Rechazada' AND OLD.estado='En revisión' AND length(trim(NEW.comentario_admin))=0 THEN RAISE EXCEPTION 'Escribe un comentario para devolver la auditoría'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_audit_change BEFORE UPDATE ON public.auditorias FOR EACH ROW EXECUTE FUNCTION public.validate_audit_update();
CREATE INDEX audit_supervisor ON public.auditorias(supervisor_id); CREATE INDEX audit_installation ON public.auditorias(instalacion_id); CREATE INDEX evidence_audit ON public.evidencias(auditoria_id);
CREATE POLICY rca_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='rca-documents' AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.rcas r WHERE r.archivo_path=name)));
CREATE POLICY rca_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='rca-documents' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY rca_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='rca-documents' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY evidence_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='audit-evidence' AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.evidencias e WHERE e.archivo_path=name)));
CREATE POLICY evidence_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='audit-evidence' AND EXISTS(SELECT 1 FROM public.auditorias a WHERE a.id::text=(storage.foldername(name))[1] AND a.estado IN ('Asignada','En progreso','Rechazada') AND (a.supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY evidence_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='audit-evidence' AND EXISTS(SELECT 1 FROM public.auditorias a WHERE a.id::text=(storage.foldername(name))[1] AND a.estado IN ('Asignada','En progreso','Rechazada') AND (a.supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));